# Keyword-gap pages (11-06): /check-engine-light/ and /best-gas-mileage/. Run by build.py with exec(). Data: data/gap.json from data_gap.py.
GAP = _load('data/gap.json') if os.path.exists('data/gap.json') else None
GAP_URLS = []
def _gap_pages():
    if not GAP: return
    T = lambda head, rows: '<div class="tw"><table class="adv"><thead><tr>' + ''.join(f'<th>{h}</th>' for h in head) + '</tr></thead><tbody>' + ''.join('<tr>' + ''.join(f'<td>{c}</td>' for c in r) + '</tr>' for r in rows) + '</tbody></table></div>'
    link = lambda r, y=None: f'<a href="/cars/{r["id"]}/{str(y) + "/" if y else ""}">{E(r["name"])}{" " + str(y) if y else ""}</a>'
    faq = [('What does a solid check engine light mean?', 'The car&#39;s computer found a fault it wants checked. The car is usually safe to drive to a shop soon. Start with the gas cap, because a loose one can trigger the light.'),
           ('What does a flashing check engine light mean?', 'A flashing light usually means the engine is misfiring badly enough to damage the catalytic converter. Slow down and get it looked at right away. If the car shakes or loses power, pull over somewhere safe.'),
           ('Can I read the code myself?', 'Yes. Any car from 1996 on has an OBD-II port under the dash. A cheap scanner reads the code, and many parts stores will read it for free.'),
           ('Which cars get the check engine light most?', f'In owner complaints to the government, {GAP["cel"][0]["name"]}, {GAP["cel"][1]["name"]} and {GAP["cel"][2]["name"]} mention it most per car sold, model years 2010 to 2022.')]
    top = GAP['cel'][:20]; yrs = GAP['cel_years'][:20]
    body = (f'<div class="advp"><header class="advh1"><p class="ph-e"><a href="/">The Lemon Index</a></p><h1>Check engine light: what it means, and which cars get it most.</h1><p>Solid means get it checked soon. Flashing means slow down and get it checked now. Below is every model ranked by how often owners mention it to the government.</p></header>'
            '<div class="ygrid"><section class="yc" id="meaning"><h2>What to do</h2><ul class="fx"><li><b>Solid light:</b> tighten the gas cap, then book a check. Most causes aren&#39;t emergencies, but don&#39;t ignore it.</li><li><b>Flashing light:</b> ease off the gas and get to a shop now. It usually means a misfire that can damage the catalytic converter.</li><li><b>Light plus other warnings:</b> if the temperature gauge is high, oil light is on, or the car shakes, stop somewhere safe.</li><li><b>Read the code:</b> a cheap OBD-II scanner works on any car from 1996 on, and many parts stores read codes for free.</li></ul></section>'
            f'<section class="yc" id="models"><h2>Models with the most check engine complaints</h2>' + T(['Model', 'Per 100K sold', 'Complaints', 'Share of its complaints'], [[link(r), f'{r["per"]:g}', f'{r["n"]:,}', f'{r["share"]}%'] for r in top]) + f'<p class="yc-cap">Model years 2010 to 2022. The typical model on our site sits at {GAP["cel_med"]:g} per 100,000 sold.</p></section>'
            f'<section class="yc" id="years"><h2>Worst single model years</h2>' + T(['Car', 'Per 100K sold', 'Complaints', 'Share of its complaints'], [[link(r, r['y']), f'{r["per"]:g}', f'{r["n"]:,}', f'{r["share"]}%'] for r in yrs]) + '<p class="yc-cap">Years with at least 15 such complaints and 20,000 sold.</p></section>'
            '<section class="yc yqa"><h2>Quick answers</h2>' + ''.join(f'<h3>{q}</h3><p>{a}</p>' for q, a in faq) + '</section></div>'
            '<p class="yc-cap">We searched the text of NHTSA owner complaints for check engine light wording. A complaint is an owner report, not a diagnosis, and owners who see a light don&#39;t always file one. This is general information, not repair advice for your car.</p></div>')
    page('/check-engine-light/', 'Check Engine Light: What It Means and Which Cars Get It Most | The Lemon Index', 'Solid or flashing check engine light: what it means and what to do, plus every model ranked by check engine complaints to the U.S. government.', body,
         ld=[faq_ld([(q, re.sub('&#39;', "'", a), None) for q, a in faq])] if False else [{"@context": "https://schema.org", "@type": "FAQPage", "mainEntity": [{"@type": "Question", "name": q, "acceptedAnswer": {"@type": "Answer", "text": html.unescape(a)}} for q, a in faq]}]); GAP_URLS.append('/check-engine-light/')
    M = GAP['mpg'][:25]; gas = sorted([m for m in GAP['mpg'] if m.get('gas')], key=lambda m: -m['gas'])[:15]; both = sorted([m for m in GAP['mpg'] if m.get('li') and m['li'] <= 80], key=lambda m: -m['comb'])[:10]
    body = (f'<div class="advp"><header class="advh1"><p class="ph-e"><a href="/">The Lemon Index</a></p><h1>Best gas mileage cars, with their complaint scores.</h1><p>EPA mileage tells you what a car saves at the pump. The Lemon Index tells you what owners complained about. Here are both, side by side.</p></header>'
            '<div class="ygrid"><section class="yc" id="both"><h2>High mileage and few complaints</h2>' + T(['Model', 'Best combined mpg', 'Lemon Index'], [[link(m), f'{m["comb"]}{" hybrid" if m["hyb"] else ""}', m['li']] for m in both]) + '<p class="yc-cap">Models with a Lemon Index of 80 or lower. 100 is the average car, lower is better.</p></section>'
            '<section class="yc" id="all"><h2>Best combined mpg, any model</h2>' + T(['Model', 'Combined', 'City / hwy', 'Fuel cost/yr', 'Lemon Index'], [[link(m) + (' (hybrid)' if m['hyb'] else ''), m['comb'], f'{m["city"]} / {m["hwy"]}', f'${m["cost"]:,}', m['li'] or '–'] for m in M]) + '</section>'
            '<section class="yc" id="gas"><h2>Best mpg without a hybrid</h2>' + T(['Model', 'Combined', 'Lemon Index'], [[link(m), m['gas'], m['li'] or '–'] for m in gas]) + '</section></div>'
            '<p class="yc-cap">Mileage: EPA, best version sold 2019 to 2025, gas and hybrid only, so no plug-ins or EVs. Fuel cost is the EPA&#39;s current estimate. Lemon Index covers model years 2010 to 2022, so a very new redesign may differ.</p></div>')
    page('/best-gas-mileage/', 'Best Gas Mileage Cars, Ranked With Owner Complaint Scores | The Lemon Index', 'The best gas mileage cars and SUVs by EPA combined mpg, next to their owner complaint scores, so you can see which ones save gas and stay out of the shop.', body); GAP_URLS.append('/best-gas-mileage/')
_gap_pages()
